// ?reloadWithBonus@Weapon@@QAE_NXZ
// partial score=0.752 date=2026-10-28
// cl: /DNDEBUG /MD /EHsc
// Open-BFME: Weapon::reloadWithBonus, retail 0x001E8720 (371 bytes).
//
// Identity: the ledger already rows this name at this RVA (thunk). The retail
// body reads m_template (+4), compares m_clipSize (template+0x4AC) and
// m_ammoInClip (+0x14), guards on RELOADING_CLIP (3) at +0x10, does the
// TheGameLogic frame / __ftol2 reload-delay math into +0x28/+0x18, fans out
// over 4 weapon slots via WeaponSet, and finishes with the rowed
// rebuildScatterTargets (ILT 0x00040589). Callees match ZH reloadWithBonus
// call-for-call: bfmeQueryERT (ILT 0x000413B2), findObjectByID (ILT
// 0x0001F253), getClipReloadTime (0x001E1680), getWeaponInWeaponSlot (ILT
// 0x0003C8E9), rebuildScatterTargets (ILT 0x00040589), __ftol2, plus the
// WeaponSet::isSharedReloadTime body at 0x001EB140 where ZH calls
// sourceObj->isReloadTimeShared() (twice, matching the two call sites).
//
// BFME1 deltas vs ZH GeneralsMD Weapon::reloadWithBonus: the early-return and
// the unlimited-ammo checks consult the owner's ammo provider (the
// BfmeHostERT/BfmeAmmoProvider pattern shared with landed
// Weapon_getRemainingAmmo.cpp, retail 0x001E5660); the status store is
// guarded; the delay math runs through double-precision x87 (__ftol2); the
// shared-reload fan-out writes member slots directly. Sibling evidence:
// - BfmeHostERT/bfmeQueryERT view and ILT 0x000413B2 routing: BfmeConv1961.cpp,
//   Weapon_getRemainingAmmo.cpp.
// - findObjectByID (82 B at 0x0009A510, ILT 0x0001F253): SelectionAll00595230.cpp.
// - getClipReloadTime (0x001E1680): rowed in Weapon.cpp, "reloadWithBonus
//   caller ... prove identity".
// - WeaponSet::isSharedReloadTime (17 B at 0x001EB140): null-checks
//   m_curWeaponTemplateSet (+4) and reads the shared flag (+0xE8), i.e. the
//   staged WeaponSet.cpp body with the ZH-inline
//   WeaponTemplateSet::isSharedReloadTime folded in. Pinned in symbols.csv.
// - Object::m_weaponSet at +0x264: bfme_layouts.json (612); the two retail
//   lea/add sites compute exactly &m_weaponSet.
// - m_frame at GameLogic+0x3C: ObjectDefectionHelperUpdate.cpp view.
// Donors: ZH GeneralsMD .../GameLogic/Object/Weapon.cpp reloadWithBonus;
// BFME2 Code/.../Object/WeaponReloadWithBonus.cpp (BFME1-donated port, diverged).
// BFME2's "false lead" verdict on its own 0x001E8720 (LocomotorSet::DoXfer
// range) is a different binary's address, not this body.

typedef unsigned int UnsignedInt;
typedef int Int;
typedef int ObjectID;
typedef bool Bool;
typedef float Real;

class WeaponBonus
{
};

// This view matches the retail definition in BfmeConv1961.cpp. The
// 0x000413B2 thunk used here routes to BfmeHostERT::bfmeQueryERT.
class BfmeHostERT
{
public:
	char bfmeQueryERT();

	int m_bfmeIndexERT;
};

class BfmeAmmoProvider
{
public:
	virtual void slot00(); virtual void slot01(); virtual void slot02(); virtual void slot03();
	virtual void slot04(); virtual void slot05(); virtual void slot06(); virtual void slot07();
	virtual void slot08(); virtual void slot09(); virtual void slot10(); virtual void slot11();
	virtual void slot12(); virtual void slot13(); virtual void slot14(); virtual void slot15();
	virtual void slot16(); virtual void slot17(); virtual void slot18(); virtual void slot19();
	virtual void slot20(); virtual void slot21(); virtual void slot22(); virtual void slot23();
	virtual void slot24(); virtual void slot25(); virtual void slot26(); virtual void slot27();
	virtual void slot28(); virtual void slot29(); virtual void slot30(); virtual void slot31();
	virtual void slot32(); virtual void slot33(); virtual void slot34(); virtual void slot35();
	virtual void slot36(); virtual void slot37(); virtual void slot38(); virtual void slot39();
	virtual void slot40(); virtual void slot41(); virtual void slot42(); virtual void slot43();
	virtual void slot44(); virtual void slot45(); virtual void slot46(); virtual void slot47();
	virtual void slot48(); virtual void slot49(); virtual void slot50(); virtual void slot51();
	virtual void slot52(); virtual void slot53(); virtual void slot54(); virtual void slot55();
	virtual void slot56(); virtual void slot57(); virtual void slot58(); virtual void slot59();
	virtual void slot60(); virtual void slot61(); virtual void slot62(); virtual void slot63();
	virtual UnsignedInt getRemainingAmmo(const BfmeHostERT *descriptor);
};

enum WeaponSlotType
{
	PRIMARY_WEAPON = 0,
	SECONDARY_WEAPON,
	TERTIARY_WEAPON,
	// Retail fans out over four slots (cmp edi,4); no fourth EA name is
	// established, so the count is spelled without inventing one.
	WEAPONSLOT_COUNT = 4
};

enum WeaponStatus
{
	READY_TO_FIRE,
	OUT_OF_AMMO,
	BETWEEN_FIRING_SHOTS,
	RELOADING_CLIP,
	PRE_ATTACK
};

class Weapon;

// WeaponSet layout per retail: m_curWeaponTemplateSet at +4 (Snapshot vtable
// at +0), m_weapons at +8. isSharedReloadTime is the 17-byte body at
// 0x001EB140 (pinned); getWeaponInWeaponSlot is the 11-byte body at
// 0x001EAF90 (rowed, reached via ILT 0x0003C8E9).
class WeaponSet
{
public:
	Weapon *getWeaponInWeaponSlot(WeaponSlotType wslot) const;
	Bool isSharedReloadTime() const;

	const void *m_snapshotBase;
	const void *m_curWeaponTemplateSet;
	Weapon *m_weapons[WEAPONSLOT_COUNT];
};

class Object
{
public:
	BfmeAmmoProvider *getAmmoProvider() const { return m_contain; }
	Bool isReloadTimeShared() const { return m_weaponSet.isSharedReloadTime(); }
	Weapon *getWeaponInWeaponSlot(WeaponSlotType wslot) const { return m_weaponSet.getWeaponInWeaponSlot(wslot); }

	char m_pad0[0x1fc];
	BfmeAmmoProvider *m_contain;
	char m_pad200[0x264 - 0x200];
	WeaponSet m_weaponSet;
};

// Retail's global at 0x012F0898 is EA's `GameLogic *TheGameLogic`, defined once
// in game/GameEngine/Source/GameLogic/System/GameLogic.cpp. m_frame sits at
// +0x3C (same view as ObjectDefectionHelperUpdate.cpp).
class GameLogic
{
public:
	Object *findObjectByID(ObjectID id);
	UnsignedInt getFrame() { return m_frame; }

	char m_pad[0x3c];
	UnsignedInt m_frame;
};

extern GameLogic *TheGameLogic;

// m_clipSize at +0x4AC, ammo descriptor at +0x4E8 (same placement as landed
// Weapon_getRemainingAmmo.cpp). getClipReloadTime is the rowed 107-byte body
// at 0x001E1680.
class WeaponTemplate
{
public:
	Int getClipSize() const { return m_clipSize; }
	Int getClipReloadTime(const WeaponBonus &bonus) const;

	char m_pad[0x4ac];
	Int m_clipSize;
	BfmeHostERT m_ammoDescriptor;
};

class Weapon
{
public:
	virtual void unused();
	void setPossibleNextShotFrame(UnsignedInt frame) { m_whenWeCanFireAgain = frame; }
	WeaponStatus getStatus() const { return m_status; }

protected:
	void reloadWithBonus(const Object *sourceObj, const WeaponBonus &bonus, Bool loadInstantly);
	void rebuildScatterTargets();
	void setStatus(WeaponStatus status) { m_status = status; }

	WeaponTemplate *m_template;
	ObjectID m_ownerID;
	UnsignedInt m_weaponSlot;
	WeaponStatus m_status;
	UnsignedInt m_ammoInClip;
	UnsignedInt m_whenWeCanFireAgain;
	char m_pad1C[0x28 - 0x1c];
	UnsignedInt m_whenLastReloadStarted;
};

void Weapon::reloadWithBonus(const Object *sourceObj, const WeaponBonus &bonus, Bool loadInstantly)
{
	if (m_template->getClipSize() > 0)
	{
		UnsignedInt remaining;
		if (m_template->m_ammoDescriptor.bfmeQueryERT())
		{
			Object *owner = TheGameLogic->findObjectByID(m_ownerID);
			BfmeAmmoProvider *provider = owner ? owner->getAmmoProvider() : 0;
			if (provider)
				remaining = provider->getRemainingAmmo(&m_template->m_ammoDescriptor);
			else
				remaining = m_ammoInClip;
		}
		else
			remaining = m_ammoInClip;
		if (remaining == m_template->getClipSize()
			&& !sourceObj->isReloadTimeShared())
			return;	// don't restart our reload delay.
	}

	m_ammoInClip = m_template->getClipSize();
	UnsignedInt providerAmmo;
	if (m_template->m_ammoDescriptor.bfmeQueryERT())
	{
		Object *owner = TheGameLogic->findObjectByID(m_ownerID);
		BfmeAmmoProvider *provider = owner ? owner->getAmmoProvider() : 0;
		if (provider)
			providerAmmo = provider->getRemainingAmmo(&m_template->m_ammoDescriptor);
		else
			providerAmmo = m_ammoInClip;
	}
	else
		providerAmmo = m_ammoInClip;
	if (providerAmmo <= 0)
		m_ammoInClip = 0x7fffffff;	// 0 == unlimited (or effectively so)

	if (m_status != RELOADING_CLIP)
		m_status = RELOADING_CLIP;

	Int reloadTime;
	if (loadInstantly)
		reloadTime = 0;
	else
		reloadTime = m_template->getClipReloadTime(bonus);

	m_whenWeCanFireAgain = (UnsignedInt)((double)reloadTime + (m_whenLastReloadStarted = TheGameLogic->getFrame()));

	// If we are sharing reload times, go through the other weapons in the
	// weapon set: set their m_whenWeCanFireAgain to this guy's delay and
	// their m_status to this guy's status.
	if (sourceObj->isReloadTimeShared())
	{
		for (Int wt = 0; wt < WEAPONSLOT_COUNT; wt++)
		{
			Weapon *weapon = sourceObj->getWeaponInWeaponSlot((WeaponSlotType)wt);
			if (weapon)
			{
				weapon->setPossibleNextShotFrame(m_whenWeCanFireAgain);
				if (weapon->getStatus() != RELOADING_CLIP)
					weapon->setStatus(RELOADING_CLIP);
			}
		}
	}

	rebuildScatterTargets();
}
